-- SEED 23 · Hindi names and descriptions for all 100 menu expansion dishes.
-- Keep the Hindi catalog content with the menu seed so local resets and hosted
-- deployments expose the same complete Hindi customer experience.
update public.products as p
set name_hi = t.name_hi,
    short_description_hi = t.short_description_hi,
    description_hi = t.description_hi
from (values
  ('lucknowi-chicken-dum-biryani', 'लखनऊवी चिकन दम बिरयानी', 'पुराने बासमती चावल, नरम चिकन, केसर के दूध और अवधी मसालों की सुगंधित परतें', 'पुराने बासमती चावल में नरम चिकन, केसर का दूध और अवधी साबुत मसालों की परतें लगाकर सीलबंद हांडी में धीमी दम पर पकाया जाता है। ऊपर से तले प्याज़, पुदीना और नींबू; ठंडे बूंदी रायते और मिर्ची के सालन के साथ परोसी जाती है।'),
  ('kolkata-chicken-biryani', 'कोलकाता चिकन बिरयानी', 'लंबे दाने वाले बासमती चावल, रसीला चिकन और धीमी आँच पर पका आलू', 'लंबे दाने वाले बासमती चावल और मसालेदार चिकन को कोलकाता अंदाज़ के हल्के मसालों के साथ दम पर पकाया जाता है। साथ में धीमी आँच पर पका आलू, उबला अंडा और सुनहरे प्याज़; खीरे के रायते के साथ परोसते हैं।'),
  ('hyderabadi-chicken-65-biryani', 'हैदराबादी चिकन 65 बिरयानी', 'मसालेदार चिकन 65, बासमती चावल, हरी मिर्च और सुनहरा प्याज़', 'चिकन 65, बासमती चावल, हरी मिर्च और सुनहरे प्याज़ को दम की परतों में सजाकर चटपटे दक्कनी मसाले के साथ पकाया जाता है। ऊपर से करी पत्ता और ताज़ा धनिया; पुदीने के रायते के साथ परोसी जाती है।'),
  ('andhra-chilli-chicken-biryani', 'आंध्र चिली चिकन बिरयानी', 'नरम चिकन, खुशबूदार चावल और तीखी आंध्र लाल मिर्च', 'नरम चिकन और खुशबूदार चावल को आंध्र की लाल मिर्च वाले तेज़ मसाले के साथ धीमी दम पर पकाया जाता है। ऊपर से तले करी पत्ते और धनिया; ठंडे खीरे के रायते के साथ परोसते हैं।'),
  ('chicken-keema-biryani', 'चिकन कीमा बिरयानी', 'बारीक चिकन कीमा, पुराने बासमती चावल और साबुत गरम मसाले', 'बारीक चिकन कीमे को कड़ाही में भूनकर पुराने बासमती चावल और साबुत मसालों की परतों के साथ दम पर पकाया जाता है। पुदीना, भुना प्याज़ और नींबू से सजाकर सादे रायते के साथ परोसते हैं।'),
  ('awadhi-mutton-yakhni-biryani', 'अवधी मटन यख़नी बिरयानी', 'धीमी आँच पर पका बकरे का मांस, खुशबूदार यख़नी और पुराने बासमती चावल', 'नरम बकरे के मांस और खुशबूदार यख़नी को पुराने बासमती चावल के साथ सावधानी से परतों में लगाकर सीलबंद हांडी में देर तक दम पर पकाया जाता है। केसर, पुदीना और कुरकुरे प्याज़ के साथ; हल्के मसाले वाले रायते के साथ परोसते हैं।'),
  ('kolkata-mutton-biryani', 'कोलकाता मटन बिरयानी', 'नरम बकरे का मांस, खुशबूदार चावल और धीमी आँच पर पका आलू', 'बकरे के नरम टुकड़ों और खुशबूदार चावल को कोलकाता अंदाज़ के हल्के मसालों के साथ लंबे दम पर पकाया जाता है। साथ में धीमी आँच पर पका आलू, सुनहरे प्याज़ और उबला अंडा; ठंडे खीरे के रायते के साथ परोसते हैं।'),
  ('egg-masala-dum-biryani', 'अंडा मसाला दम बिरयानी', 'मसाले में लिपटे अंडे, पुराने बासमती चावल और सुनहरे प्याज़', 'मसाले में लिपटे उबले अंडों को पुराने बासमती चावल और भुने प्याज़ की परतों के साथ साबुत मसालों के दम पर पकाया जाता है। ताज़े धनिये और पुदीने से सजाकर बूंदी रायते के साथ परोसते हैं।'),
  ('paneer-tikka-biryani', 'पनीर टिक्का बिरयानी', 'तंदूर में सिका पनीर टिक्का, केसरिया बासमती चावल और चटपटा मसाला', 'तंदूर में सिका पनीर टिक्का और केसरिया बासमती चावल को हल्के काली मिर्च वाले मसाले के साथ परतों में लगाकर धीमी दम पर पकाया जाता है। पुदीना, तले प्याज़ और भुने काजू से सजाकर पुदीने के रायते के साथ परोसते हैं।'),
  ('mushroom-pepper-biryani', 'मशरूम पेपर बिरयानी', 'रसीले मशरूम, पुराने बासमती चावल और कुटी काली मिर्च', 'रसीले बटन मशरूम और पुराने बासमती चावल को कुटी काली मिर्च के साथ कड़ाही में मिलाकर धीमी दम पर पकाया जाता है। धनिया, पुदीना और सुनहरे प्याज़ से सजाकर सादे रायते के साथ परोसते हैं।'),
  ('chicken-chettinad', 'चिकन चेट्टीनाड करी', 'चिकन, भुनी काली मिर्च, सौंफ, नारियल और करी पत्ते', 'चिकन को भुनी काली मिर्च, सौंफ, नारियल और करी पत्तों के साथ ताज़ा पिसे चेट्टीनाड मसाले में धीमी आँच पर पकाया जाता है। करी पत्ते और धनिये से सजाकर भाप के चावल या लच्छा पराठे के साथ परोसते हैं।'),
  ('kadai-chicken', 'कड़ाही चिकन', 'चिकन, कुटा धनिया, शिमला मिर्च और पके टमाटर', 'चिकन को कुटे धनिये, शिमला मिर्च और पके टमाटर के साथ लोहे की कड़ाही में तेज़ आँच पर पकाया जाता है। अदरक की पतली कतरन और ताज़े धनिये से सजाकर बटर नान के साथ परोसते हैं।'),
  ('chicken-lababdar', 'चिकन लबाबदार', 'अंगारों पर सिका चिकन, टमाटर, काजू और हल्की मलाई', 'अंगारों पर सिका चिकन टमाटर, काजू और मलाईदार उत्तर भारतीय ग्रेवी में धीमी आँच पर पकाया जाता है। मक्खन, क्रीम और धनिये से सजाकर तंदूरी रोटी के साथ परोसते हैं।'),
  ('chicken-handi-curry', 'चिकन हांडी करी', 'हड्डी वाला चिकन, प्याज़, टमाटर, अदरक और घर का गरम मसाला', 'हड्डी वाले चिकन को प्याज़, टमाटर, अदरक और घर के गरम मसाले के साथ ढकी हांडी में तब तक पकाया जाता है, जब तक करी गाढ़ी और चिकन नरम न हो जाए। अदरक, धनिया और थोड़ी क्रीम के साथ; भाप के बासमती चावल के साथ परोसते हैं।'),
  ('chicken-do-pyaza', 'चिकन दो प्याज़ा', 'चिकन, मीठे प्याज़ की कलियाँ, टमाटर और भुना जीरा', 'चिकन को प्याज़ की दो तरह की बनावट, टमाटर और भुने जीरे के साथ धीमी आँच पर पकाया जाता है। जला हुआ प्याज़, धनिया और नींबू से सजाकर रूमाली रोटी के साथ परोसते हैं।'),
  ('pepper-chicken-roast', 'पेपर चिकन रोस्ट', 'रसीला चिकन, कुटी काली मिर्च, लहसुन और करी पत्ते', 'चिकन को कुटी काली मिर्च, लहसुन और करी पत्तों के साथ तवे पर भूनते हैं, ताकि मसाला हर टुकड़े पर अच्छी तरह लिपट जाए। ताज़े करी पत्ते और नींबू के साथ; जीरा चावल के साथ परोसते हैं।'),
  ('chicken-kolhapuri', 'चिकन कोल्हापुरी', 'चिकन, सूखा नारियल, तिल और कोल्हापुरी लाल मिर्च', 'चिकन को सूखे नारियल, तिल और कोल्हापुरी लाल मिर्च के भुने हुए तीखे मसाले में धीमी आँच पर पकाया जाता है। धनिया और भुने तिल से सजाकर बटर रोटी के साथ परोसते हैं।'),
  ('mughlai-chicken-korma', 'मुगलई चिकन कोरमा', 'नरम चिकन, दही, काजू और खुशबूदार इलायची', 'नरम चिकन को दही, काजू और इलायची के साथ धीमी आँच पर पकाकर शाही, मलाईदार कोरमा बनाया जाता है। केसर वाली क्रीम और भुने बादाम से सजाकर नान या केसरिया चावल के साथ परोसते हैं।'),
  ('chicken-saagwala', 'चिकन सागवाला', 'चिकन, धीमी आँच पर पका पालक, लहसुन और जीरा', 'चिकन और पालक को लहसुन व जीरे के साथ धीमी आँच पर पकाकर भरपूर, मिट्टी-सी खुशबू वाली करी बनाई जाती है। अदरक और थोड़ी क्रीम से सजाकर मक्के की रोटी या भाप के चावल के साथ परोसते हैं।'),
  ('chicken-tikka-masala', 'चिकन टिक्का मसाला', 'कोयले की खुशबू वाला चिकन टिक्का, टमाटर और काजू', 'कोयले पर सिका चिकन टिक्का टमाटर और काजू की हल्की धुएँदार मखनी ग्रेवी में पकाया जाता है। क्रीम, धनिया और अदरक से सजाकर बटर नान के साथ परोसते हैं।'),
  ('mutton-rogan-josh', 'कश्मीरी मटन रोगन जोश', 'धीमी आँच पर पका बकरे का मांस, कश्मीरी मिर्च, सौंफ और सोंठ', 'बकरे के मांस को कश्मीरी मिर्च, सौंफ और सोंठ के साथ बहुत धीमी आँच पर गाढ़ी, खुशबूदार ग्रेवी में पकाया जाता है। ऊपर से दही और धनिये की हल्की परत; केसरिया चावल के साथ परोसते हैं।'),
  ('mutton-keema-masala', 'मटन कीमा मसाला', 'हाथ से कुटा बकरे का कीमा, मटर, टमाटर और भुना जीरा', 'बकरे के कीमे को मटर, टमाटर और भुने जीरे के साथ अच्छी तरह भूनते हैं, जब तक मसाला गाढ़ा और चमकदार न हो जाए। हरी मिर्च और ताज़े धनिये से सजाकर बटर पाव या पराठे के साथ परोसते हैं।'),
  ('mutton-bhuna', 'मटन भुना मसाला', 'बकरे का मांस, भुना प्याज़, टमाटर और कुटी काली मिर्च', 'बकरे के टुकड़ों को भुने प्याज़, टमाटर और कुटी काली मिर्च के साथ धीमी आँच पर भूनकर पकाया जाता है, ताकि गाढ़ा मसाला मांस पर अच्छी तरह चढ़ जाए। अदरक की कतरन और धनिये से सजाकर तंदूरी रोटी के साथ परोसते हैं।'),
  ('mutton-rara', 'मटन रारा', 'बकरे के टुकड़े और कीमा, टमाटर व साबुत गरम मसालों के साथ', 'बकरे के टुकड़ों और कीमे को टमाटर व साबुत गरम मसालों के साथ एक साथ पकाकर भरपूर उत्तर भारतीय करी बनाई जाती है। अदरक, हरी मिर्च और धनिये से सजाकर सादे कुलचे के साथ परोसते हैं।'),
  ('mutton-korma', 'मटन कोरमा', 'बकरे का मांस, दही, भुना प्याज़ और खुशबूदार काजू', 'बकरे के मांस को दही, भुने प्याज़ और काजू की मलाईदार कोरमा ग्रेवी में धीमी आँच पर नरम होने तक पकाया जाता है। केसर, भुने बादाम और धनिये से सजाकर रूमाली रोटी के साथ परोसते हैं।'),
  ('pepper-mutton-fry', 'पेपर मटन फ्राई', 'नरम बकरे का मांस, कुटी काली मिर्च, लहसुन और करी पत्ते', 'बकरे के नरम मांस को कुटी काली मिर्च, लहसुन और करी पत्तों के साथ धीमी आँच पर पकाकर सूखे मसाले में तवे पर भूनते हैं। तले करी पत्ते और नींबू के साथ; घी चावल के साथ परोसते हैं।'),
  ('mutton-saagwala', 'मटन सागवाला', 'बकरे का मांस, पालक, लहसुन और भुना जीरा', 'बकरे के टुकड़ों को पालक, लहसुन और भुने जीरे की गाढ़ी हरी ग्रेवी में नरम होने तक पकाया जाता है। अदरक और थोड़ी क्रीम से सजाकर जीरा चावल के साथ परोसते हैं।'),
  ('chicken-seekh-kathi-roll', 'चिकन सीख काठी रोल', 'अंगारों पर सिकी चिकन सीख, परतदार पराठा, प्याज़ और पुदीने की चटनी', 'चिकन सीख को अंगारों पर भूनकर परतदार पराठे में प्याज़ और पुदीने की चटनी के साथ भरते हैं। ऑर्डर पर गरम तवे पर हल्का सेंककर नींबू, अचार वाले प्याज़, पुदीने और हरी चटनी के साथ परोसते हैं।'),
  ('afghani-chicken-roll', 'अफ़गानी चिकन रोल', 'मलाईदार अफ़गानी चिकन टिक्का, नरम पराठा और कुरकुरा सलाद पत्ता', 'अफ़गानी अंदाज़ के चिकन टिक्के को तंदूर में भूनकर नरम पराठे में ताज़ा लपेटते हैं। पुदीने की चटनी और प्याज़ के साथ, ठंडे लाइम सोडा के संग परोसते हैं।'),
  ('chicken-65-paratha-roll', 'चिकन 65 पराठा रोल', 'कुरकुरा चिकन 65, परतदार पराठा और चिली-लहसुन सलाद', 'कुरकुरे चिकन 65 को दक्षिण भारतीय तीखे मसाले में मिलाकर प्याज़ और चिली-लहसुन सलाद के साथ पराठे में रोल करते हैं। करी पत्ते और नींबू से सजाकर घर की पुदीना डिप के साथ परोसते हैं।'),
  ('mutton-keema-paratha-roll', 'मटन कीमा पराठा रोल', 'धीमी आँच पर पका मटन कीमा, अंडे की परत वाला पराठा और प्याज़', 'धीमी आँच पर पके मटन कीमे को अंडे की परत वाले पराठे में भरकर तवे पर कुरकुरी किनारी और नरम भरावन आने तक सेंकते हैं। धनिया, नींबू और हरी चटनी के साथ; मसाला छाछ के संग परोसते हैं।'),
  ('paneer-kathi-roll', 'पनीर काठी रोल', 'तंदूरी पनीर, शिमला मिर्च, परतदार पराठा और पुदीने की चटनी', 'तंदूरी पनीर और शिमला मिर्च को गरम तवे पर हल्का सेंककर परतदार पराठे में लपेटते हैं। अचार वाले प्याज़ और धनिये से सजाकर पुदीने-दही की डिप के साथ परोसते हैं।'),
  ('aloo-tikki-kathi-roll', 'आलू टिक्की काठी रोल', 'कुरकुरी आलू टिक्की, छोले मसाला, प्याज़ और हरी चटनी', 'आलू टिक्की और छोले मसाले को नरम परतदार पराठे में भरकर तवे पर हल्का कुरकुरा सेंकते हैं। इमली की चटनी और धनिये के साथ; मीठी लस्सी के संग परोसते हैं।'),
  ('soya-chaap-kathi-roll', 'सोया चाप काठी रोल', 'धुएँ की खुशबू वाली सोया चाप, शिमला मिर्च और टिक्का मेरिनेड', 'सोया चाप को घर के टिक्का मसाले में मेरिनेट करके अंगारों पर भूनते हैं, फिर काटकर ताज़े पराठे में लपेटते हैं। पुदीने की चटनी, प्याज़ और नींबू के साथ; मसाला छाछ के संग परोसते हैं।'),
  ('egg-masala-kathi-roll', 'अंडा मसाला काठी रोल', 'फेंटा हुआ मसाला अंडा, प्याज़ और हरी मिर्च', 'गरम पराठे पर मसालेदार अंडे की परत फैलाकर पकाते हैं और फिर प्याज़ व चटनी के साथ रोल करते हैं। धनिये और टमाटर की चटनी के साथ; अदरक वाली चाय के संग परोसते हैं।'),
  ('chicken-chow-mein', 'चिकन चाउमीन', 'वॉक में भुने नूडल्स, चिकन के टुकड़े, पत्तागोभी और हरा प्याज़', 'नूडल्स और चिकन के टुकड़ों को पत्तागोभी व हरे प्याज़ के साथ तेज़ आँच पर वॉक में भूनते हैं। घर के सोया मसाले से स्वाद देकर ऊपर से हरा प्याज़ और भुने तिल डालते हैं; चिली विनेगर के साथ परोसते हैं।'),
  ('veg-garlic-noodles', 'गार्लिक वेज हक्का नूडल्स', 'हक्का नूडल्स, मौसमी सब्ज़ियाँ और सुनहरा लहसुन', 'हक्का नूडल्स और मौसमी सब्ज़ियों को सुनहरे लहसुन के साथ तेज़ आँच पर वॉक में झटपट भूनते हैं। ऊपर से हरा प्याज़ और तिल डालकर कुरकुरे चिली ऑयल के साथ परोसते हैं।'),
  ('schezwan-veg-noodles', 'शेज़वान वेज नूडल्स', 'नूडल्स, शिमला मिर्च और पत्तागोभी पर चिली-लहसुन सॉस', 'नूडल्स, शिमला मिर्च और पत्तागोभी को तेज़ आँच पर वॉक में शेज़वान चिली-लहसुन सॉस के साथ भूनते हैं। हरे प्याज़ और तिल से सजाकर ठंडे खीरे के सलाद व चिली विनेगर के साथ परोसते हैं।'),
  ('singapore-veg-noodles', 'सिंगापुर वेज नूडल्स', 'करी वाले चावल के नूडल्स, शिमला मिर्च, पत्तागोभी और गाजर', 'चावल के नूडल्स को शिमला मिर्च, पत्तागोभी और गाजर के साथ खुशबूदार सिंगापुर मसाले में वॉक पर जल्दी भूनते हैं। हरे प्याज़ और नींबू से सजाकर चिली विनेगर के साथ परोसते हैं।'),
  ('egg-fried-rice', 'अंडा फ्राइड राइस', 'वॉक में भुने चावल, नरम अंडा, हरा प्याज़ और ताज़ी सब्ज़ियाँ', 'चावल, नरम अंडे और बगीचे की ताज़ी सब्ज़ियों को तेज़ आँच पर वॉक में भूनते हैं, ताकि हर दाना अलग और स्वादिष्ट रहे। ऊपर से हरा प्याज़ और भुने तिल डालकर चिली-लहसुन सॉस के साथ परोसते हैं।'),
  ('chicken-fried-rice', 'चिकन फ्राइड राइस', 'वॉक में सिका चिकन, बासमती चावल, अंडा और कुरकुरी सब्ज़ियाँ', 'चिकन, बासमती चावल, अंडे और कुरकुरी सब्ज़ियों को घर के संतुलित मसाले में तेज़ आँच पर वॉक में भूनते हैं। हरे प्याज़ और तिल से सजाकर चिली विनेगर के साथ परोसते हैं।'),
  ('schezwan-veg-fried-rice', 'शेज़वान वेज फ्राइड राइस', 'भाप के चावल, सब्ज़ियाँ और घर की चिली-लहसुन सॉस', 'भाप में पके चावल और ताज़ी सब्ज़ियों को घर की तीखी चिली-लहसुन सॉस के साथ तेज़ आँच पर वॉक में भूनते हैं। हरे प्याज़ और कुरकुरे लहसुन से सजाकर ठंडे खीरे के सलाद के साथ परोसते हैं।'),
  ('schezwan-chicken-fried-rice', 'शेज़वान चिकन फ्राइड राइस', 'चिकन, चावल, शिमला मिर्च और तीखी शेज़वान मिर्च', 'चिकन, चावल और शिमला मिर्च को तीखी शेज़वान मिर्च के साथ तेज़ आँच पर वॉक में भूनते हैं। हरे प्याज़ और तिल से सजाकर चिली विनेगर के साथ परोसते हैं।'),
  ('dragon-paneer', 'ड्रैगन पनीर', 'कुरकुरा पनीर, शिमला मिर्च और चिपचिपी चिली-लहसुन सॉस', 'पनीर और शिमला मिर्च को कुरकुरा तलकर ऑर्डर पर चिली-लहसुन की चटपटी ड्रैगन सॉस में वॉक पर मिलाते हैं। तिल, हरे प्याज़ और लाल मिर्च से सजाकर भाप के चावल के साथ परोसते हैं।'),
  ('honey-chilli-potato', 'हनी चिली पोटैटो', 'कुरकुरी आलू की फाँकें, शहद, मिर्च और भुने तिल', 'आलू की फाँकों को दो बार कुरकुरा तलकर खट्टी-मीठी शहद-मिर्च सॉस में लपेटते हैं। ऊपर से तिल और हरा प्याज़ डालकर ठंडे लाइम ड्रिंक के साथ परोसते हैं।'),
  ('chicken-malai-tikka', 'चिकन मलाई टिक्का', 'रसीला चिकन, केसर, काजू, गाढ़ा दही और इलायची', 'चिकन को केसर, काजू, गाढ़े दही और इलायची में मेरिनेट करके अंगारों पर नरम और हल्की धुएँ की खुशबू आने तक भूनते हैं। क्रीम, पुदीना और नींबू के साथ; हरी चटनी के संग परोसते हैं।'),
  ('tandoori-chicken-wings', 'तंदूरी चिकन विंग्स', 'चिकन विंग्स, दही, कश्मीरी मिर्च और भुना जीरा', 'चिकन विंग्स को दही, कश्मीरी मिर्च और भुने जीरे में मेरिनेट करके मिट्टी के तंदूर में भूनते हैं, ताकि किनारे हल्के सिकें और अंदर रसदार रहें। नींबू, धनिया और चाट मसाले के साथ; पुदीने की चटनी के संग परोसते हैं।'),
  ('afghani-chicken-kebab', 'अफ़ग़ानी चिकन कबाब', 'चिकन जांघ का मांस, क्रीम, काजू और सफ़ेद मिर्च', 'चिकन को क्रीम, काजू और सफ़ेद मिर्च में धीरे-धीरे मेरिनेट करके तंदूर में भूनते हैं। केसर वाली क्रीम और ताज़े पुदीने से सजाकर रूमाली रोटी के साथ परोसते हैं।'),
  ('tangdi-kebab', 'मुर्ग तंगड़ी कबाब', 'चिकन ड्रमस्टिक, दही, अदरक और तंदूरी मसाले', 'चिकन ड्रमस्टिक को दही, अदरक और तंदूरी मसालों में मेरिनेट करके मिट्टी के तंदूर में धुएँदार और रसीला होने तक भूनते हैं। नींबू, प्याज़ के छल्ले और धनिये से सजाकर पुदीना-दही के साथ परोसते हैं।'),
  ('chicken-reshmi-kebab', 'चिकन रेशमी कबाब', 'चिकन कीमा, काजू, क्रीम और हल्की सफ़ेद मिर्च', 'चिकन कीमे को काजू, क्रीम और हल्की सफ़ेद मिर्च के साथ सीख पर लगाकर तंदूर में मुलायम और सुनहरा होने तक भूनते हैं। केसर और ताज़े धनिये से सजाकर हरी चटनी के साथ परोसते हैं।'),
  ('chicken-65', 'चिकन 65', 'कुरकुरे चिकन बाइट्स, करी पत्ता, मिर्च और लहसुन', 'चिकन के टुकड़ों को मसाले में मेरिनेट करके जल्दी कुरकुरा तलते हैं और तेज़ मसाले में मिलाते हैं। करी पत्ते और नींबू से सजाकर पुदीना डिप के साथ परोसते हैं।'),
  ('fish-tikka', 'तंदूरी फिश टिक्का', 'मज़बूत बनावट वाली मछली, दही, अजवाइन और कश्मीरी मिर्च', 'मछली के टुकड़ों को दही, अजवाइन और कश्मीरी मिर्च में मेरिनेट करके सीख पर लगाते हैं और तंदूर में भूनते हैं। नींबू, धनिया और प्याज़ से सजाकर पुदीने की चटनी के साथ परोसते हैं।'),
  ('crispy-corn-pepper', 'क्रिस्पी पेपर कॉर्न', 'मीठे मकई के दाने, कुटी काली मिर्च और हल्का मसाला', 'मकई के दानों पर हल्का मसाला और काली मिर्च लगाकर कुरकुरा तला जाता है, जिससे हर दाना हल्का और चटपटा बने। करी पत्ते और नींबू से सजाकर टमाटर-मिर्च डिप के साथ परोसते हैं।'),
  ('hara-bhara-kebab', 'हरा-भरा कबाब', 'पालक, मटर, आलू और भुने काजू', 'पालक, मटर और आलू में भुने काजू मिलाकर कबाब बनाते हैं और बाहर से कुरकुरा, अंदर से नरम होने तक तवे पर सेंकते हैं। पुदीने और भुने काजू से सजाकर इमली की चटनी के साथ परोसते हैं।'),
  ('cheese-corn-pakoda', 'चीज़ कॉर्न पकौड़ा', 'मीठा मकई, चेडर चीज़, बेसन और हल्की हरी मिर्च', 'मकई, चेडर चीज़, बेसन और हल्की हरी मिर्च के घोल को छोटे कुरकुरे गुच्छों में तलते हैं। चाट मसाला और धनिये से सजाकर पुदीने की चटनी के साथ परोसते हैं।'),
  ('palak-paneer', 'पालक पनीर', 'नरम पनीर, ताज़ा पालक, लहसुन और भुना जीरा', 'नरम पनीर को ताज़े पालक, लहसुन और भुने जीरे की रेशमी हरी ग्रेवी में पकाया जाता है। क्रीम, अदरक और धनिये से सजाकर तंदूरी रोटी के साथ परोसते हैं।'),
  ('kadai-paneer', 'कड़ाही पनीर', 'पनीर, शिमला मिर्च, टमाटर और ताज़ा कुटा धनिया', 'पनीर, शिमला मिर्च और टमाटर को गरम कड़ाही में घर के दरदरे मसाले के साथ पकाते हैं। अदरक, धनिया और क्रीम से सजाकर बटर नान के साथ परोसते हैं।'),
  ('shahi-paneer', 'शाही पनीर', 'पनीर, काजू, केसर और हल्की टमाटर-क्रीम ग्रेवी', 'पनीर को काजू, केसर और टमाटर-क्रीम की मुलायम मुगलई ग्रेवी में हल्की आँच पर पकाया जाता है। केसर, क्रीम और भुने बादाम से सजाकर लच्छा पराठे के साथ परोसते हैं।'),
  ('matar-paneer', 'मटर पनीर', 'पनीर, मीठे हरे मटर, टमाटर और गरम मसाला', 'पनीर और मीठे हरे मटर को प्याज़-टमाटर की घर जैसी ग्रेवी में गरम मसाले के साथ धीमी आँच पर पकाते हैं। ताज़े धनिये और अदरक से सजाकर भाप के बासमती चावल के साथ परोसते हैं।'),
  ('mushroom-masala', 'मशरूम मसाला', 'बटन मशरूम, टमाटर, प्याज़ और भुना धनिया', 'बटन मशरूम को पहले तवे पर सेंकते हैं, फिर टमाटर, प्याज़ और भुने धनिये के गाढ़े मसाले में पकाते हैं। धनिया और अदरक से सजाकर बटर रोटी के साथ परोसते हैं।'),
  ('chole-masala', 'पंजाबी छोले मसाला', 'धीमी आँच पर पके काबुली चने, टमाटर, बड़ी इलायची और अमचूर', 'काबुली चनों को टमाटर, बड़ी इलायची और उत्तर भारतीय मसालों के साथ तब तक पकाते हैं, जब तक ग्रेवी मलाईदार न हो जाए। अदरक, धनिया और नींबू से सजाकर कुलचे या भाप के चावल के साथ परोसते हैं।'),
  ('rajma-masala', 'राजमा मसाला', 'लाल राजमा, टमाटर, प्याज़ और भुना जीरा', 'लाल राजमा को टमाटर, प्याज़ और भुने जीरे के साथ धीमी आँच पर तब तक पकाते हैं, जब तक दाने नरम और ग्रेवी गाढ़ी न हो जाए। अदरक और ताज़े धनिये से सजाकर भाप के बासमती चावल के साथ परोसते हैं।'),
  ('dal-makhani', 'दाल मखनी', 'काली दाल, राजमा, मक्खन और टमाटर', 'काली दाल और राजमा को धीमी आँच पर देर तक पकाकर गाढ़ा और मलाईदार बनाया जाता है। क्रीम, मक्खन और धनिये से सजाकर जीरा चावल के साथ परोसते हैं।'),
  ('jeera-rice', 'जीरा राइस', 'खुशबूदार बासमती चावल और घी में तड़का हुआ जीरा', 'बासमती चावल को घी में तड़के हुए जीरे के साथ भाप में पकाते हैं, ताकि हर दाना खिला-खिला और सुगंधित रहे। ऊपर से भुना जीरा और धनिया डालकर किसी भी करी के साथ परोसें।'),
  ('peas-pulao', 'मटर पुलाव', 'बासमती चावल, मीठे मटर, साबुत मसाले और सुनहरा प्याज़', 'बासमती चावल और मीठे मटर को साबुत मसालों के साथ हल्के दम पर पकाकर खुशबूदार पुलाव बनाया जाता है। पुदीना और तले प्याज़ से सजाकर रायते या गाढ़ी करी के साथ परोसते हैं।'),
  ('garlic-naan', 'गार्लिक बटर नान', 'नरम खमीर वाली नान, ताज़ा लहसुन और मक्खन', 'नरम खमीर वाले आटे की नान को तंदूर में फूलने और सुनहरी होने तक पकाते हैं। ऊपर से ताज़ा लहसुन, कटा धनिया और मक्खन लगाकर करी के साथ परोसते हैं।'),
  ('cheese-naan', 'चीज़ नान', 'पिघलने वाला चीज़, नरम नान का आटा और काली मिर्च', 'नान के नरम आटे में चीज़ भरकर हाथ से फैलाते हैं और तंदूर में सुनहरा होने तक पकाते हैं। ऊपर से मक्खन और धनिया लगाकर टिक्का मसाला के साथ परोसते हैं।'),
  ('stuffed-aloo-kulcha', 'भरवाँ आलू कुलचा', 'मसालेदार आलू, कलौंजी और नरम खमीर वाला कुलचा', 'नरम कुलचे में मसालेदार आलू भरकर तंदूर में पकाते हैं, ताकि बाहर हल्का कुरकुरा और अंदर नरम रहे। मक्खन और धनिये से सजाकर छोले मसाले के साथ परोसते हैं।'),
  ('paneer-kulcha', 'पनीर कुलचा', 'मसला हुआ पनीर, हरी मिर्च, धनिया और कलौंजी', 'मसले हुए पनीर, हरी मिर्च और धनिये की भरावन को कुलचे में भरकर हाथ से बेलते हैं और मिट्टी के तंदूर में पकाते हैं। मक्खन और चाट मसाले से सजाकर पुदीना-दही के साथ परोसते हैं।'),
  ('missi-roti', 'मिस्सी रोटी', 'गेहूँ का आटा, बेसन, अजवाइन और ताज़ा धनिया', 'गेहूँ के आटे और बेसन में अजवाइन व ताज़ा धनिया मिलाकर रोटी हाथ से बेलते हैं और गरम तवे पर सेंकते हैं। ऊपर से थोड़ा घी लगाकर साग या दाल के साथ परोसते हैं।'),
  ('tandoori-paratha', 'तंदूरी पराठा', 'परतदार गेहूँ का आटा और घी की हल्की परत', 'गेहूँ के आटे की परतदार लोइयों पर हल्का घी लगाकर तंदूर में कुरकुरी परतें बनने तक पकाते हैं। मक्खन और कलौंजी से सजाकर करी या कबाब के साथ परोसते हैं।'),
  ('rumali-roti', 'रूमाली रोटी', 'कागज़ जैसी पतली गेहूँ की रोटी, मुलायम और हल्की', 'गेहूँ के आटे की पतली रोटी को हाथ से फैलाकर उलटी गरम कड़ाही पर जल्दी सेंकते हैं, ताकि वह मुलायम और हल्की रहे। थोड़ा घी लगाकर कबाब के साथ परोसते हैं।'),
  ('butter-roti', 'तंदूरी बटर रोटी', 'गेहूँ की रोटी पर लगा पिघला मक्खन', 'गेहूँ की रोटी को तंदूर में हल्की आँच पर सेंकते हैं, जिससे उस पर हल्की सिकाई आए और अंदर से नरम रहे। ऊपर से पिघला मक्खन लगाकर किसी भी करी के साथ परोसते हैं।'),
  ('mango-lassi', 'मैंगो लस्सी', 'पका आम, ठंडा दही और इलायची की हल्की खुशबू', 'पके आम के गूदे को ठंडे दही के साथ ताज़ा फेंटकर गाढ़ी और मुलायम लस्सी बनाते हैं। केसर और पिस्ते से सजाकर ठंडी परोसते हैं।'),
  ('rose-lassi', 'रोज़ लस्सी', 'ताज़ा दही, गुलाब का शरबत और इलायची', 'ताज़े दही को गुलाब के शरबत और थोड़ी इलायची के साथ ठंडा फेंटते हैं, जिससे लस्सी मलाईदार और झागदार बने। सूखी गुलाब की पंखुड़ियों और पिस्ते से सजाकर ठंडी परोसते हैं।'),
  ('badam-milkshake', 'बादाम केसर शेक', 'बादाम, ठंडा दूध, केसर और थोड़ा शहद', 'बादाम, ठंडे दूध, केसर और थोड़े शहद को ताज़ा पीसकर गाढ़ा, मुलायम शेक बनाते हैं। केसर के धागों और कटे बादाम से सजाकर ठंडा परोसते हैं।'),
  ('mango-milkshake', 'मैंगो मिल्कशेक', 'पका आम, ठंडा दूध और वनीला', 'पके आम और ठंडे दूध को वनीला के साथ ऑर्डर पर फेंटकर मलाईदार गर्मियों का शेक बनाते हैं। आम के टुकड़ों से सजाकर ठंडा परोसते हैं।'),
  ('nimbu-soda', 'ताज़ा नींबू सोडा', 'ताज़ा नींबू, सोडा, काला नमक और भुना जीरा', 'ताज़े नींबू के रस को सोडा, काले नमक और थोड़े भुने जीरे के साथ ऑर्डर पर मिलाते हैं। मीठा या नमकीन चुनें; बर्फ, पुदीना और नींबू की फाँक के साथ परोसते हैं।'),
  ('jaljeera-cooler', 'जलजीरा कूलर', 'भुना जीरा, पुदीना, इमली और ठंडा पानी', 'भुने जीरे, पुदीने, इमली और ठंडे पानी को मिलाकर चटपटा ताज़ा पेय बनाते हैं। पुदीने की पत्तियों और बूंदी से सजाकर ठंडा परोसते हैं।'),
  ('masala-chai', 'मसाला चाय', 'ताज़ा दूध वाली चाय, अदरक, इलायची और गरम मसाले', 'दूध वाली चाय को अदरक, इलायची और घर के गरम मसालों के साथ धीमी आँच पर उबालते हैं, ताकि स्वाद अच्छी तरह घुल जाए। कुटी इलायची के साथ गरमा-गरम परोसते हैं।'),
  ('rasmalai', 'रस मलाई (2 पीस)', 'ठंडे केसरिया दूध में नरम छेना की टिक्कियाँ', 'छेना की नरम टिक्कियों को ठंडे केसरिया दूध में भिगोकर मुलायम और स्पंजी होने तक रखते हैं। पिस्ते और केसर से सजाकर ठंडी परोसते हैं।'),
  ('gajar-ka-halwa', 'गाजर का हलवा', 'धीमी आँच पर पकी गाजर, दूध, घी और इलायची', 'कद्दूकस की हुई गाजर को दूध, घी और इलायची के साथ धीमी आँच पर तब तक पकाते हैं, जब तक हलवा गाढ़ा और खुशबूदार न हो जाए। भुने काजू और बादाम से सजाकर गरम परोसते हैं।'),
  ('shahi-tukda', 'शाही टुकड़ा', 'कुरकुरी ब्रेड, केसर की रबड़ी और खुशबूदार चाशनी', 'ब्रेड के टुकड़ों को सुनहरा तलकर गाढ़े दूध और केसर की रबड़ी के साथ सजाते हैं। पिस्ते और सूखी गुलाब की पंखुड़ियों से सजाकर हल्का गरम परोसते हैं।'),
  ('matka-phirni', 'मटका फिरनी', 'पिसे चावल, ठंडा दूध, इलायची और गुलाब', 'पिसे चावल और दूध को इलायची के साथ धीमी आँच पर गाढ़ा पकाकर मिट्टी के मटके में जमाते हैं। पिस्ते और सूखी गुलाब की पंखुड़ियों से सजाकर ठंडी परोसते हैं।'),
  ('malai-kulfi', 'मलाई कुल्फी', 'गाढ़ा किया दूध, इलायची और भुना पिस्ता', 'दूध को धीमी आँच पर गाढ़ा करके इलायची और भुने पिस्ते के साथ जमाते हैं, जिससे कुल्फी घनी और मलाईदार बने। केसर और पिस्ते से सजाकर जमी हुई परोसते हैं।'),
  ('chocolate-brownie', 'गरम चॉकलेट ब्राउनी', 'डार्क चॉकलेट, कोको, मक्खन और भुना अखरोट', 'डार्क चॉकलेट, कोको और मक्खन से बनी ब्राउनी को बीच से नरम और फज जैसी रहने तक बेक करते हैं। ऊपर से गरम चॉकलेट सॉस डालकर गरम परोसते हैं।'),
  ('malpua-rabri', 'रबड़ी के साथ मालपुआ', 'सुनहरा मालपुआ, गाढ़ी रबड़ी और इलायची की चाशनी', 'मालपुए को ताज़ा तवे पर सुनहरा तलकर इलायची वाली चाशनी में थोड़ी देर भिगोते हैं। गाढ़ी रबड़ी, पिस्ते और केसर के साथ गरम परोसते हैं।'),
  ('kala-jamun', 'काला जामुन (2 पीस)', 'खोए के नरम गोले और गुलाब-इलायची की चाशनी', 'खोए के गोलों को धीमी आँच पर गहरे सुनहरे रंग तक तलकर गुलाब और इलायची की चाशनी में भिगोते हैं। गुलाब की पंखुड़ियों के साथ गरम परोसते हैं।'),
  ('butter-chicken-naan-meal', 'बटर चिकन नान मील', 'बटर चिकन, दो गार्लिक नान, प्याज़ का सलाद और रायता', 'इस पूरे एक व्यक्ति के मील में मलाईदार बटर चिकन, दो लहसुन वाली नान, प्याज़ का सलाद और रायता शामिल हैं। ताज़ा पैक करके ऊपर से क्रीम और धनिये के साथ परोसते हैं।'),
  ('paneer-makhani-meal', 'पनीर मखनी मील', 'पनीर मखनी, जीरा चावल, बटर रोटी और सलाद', 'इस संतुलित शाकाहारी मील में पनीर मखनी, जीरा चावल, मक्खन लगी रोटी और सलाद शामिल हैं। ताज़ा पैक करके क्रीम और धनिये से सजाते हैं।'),
  ('kebab-platter-for-two', 'दो लोगों के लिए तंदूरी कबाब प्लेटर', 'चिकन मलाई टिक्का, सीख कबाब, तंगड़ी और रूमाली रोटी', 'चिकन मलाई टिक्का, सीख कबाब और तंगड़ी को कोयले वाले तंदूर में भूनकर साझा करने के लिए सजाते हैं। पुदीने की चटनी, प्याज़ और नींबू के साथ; तीन तरह की चटनी और रूमाली रोटी सहित दो लोगों के लिए परोसते हैं।'),
  ('mutton-feast-box', 'चंपारण मटन फीस्ट बॉक्स', 'चंपारण अंदाज़ का बकरे का करी, बासमती चावल, दो रोटियाँ और सलाद', 'चंपारण अंदाज़ के बकरे के मांस को हांडी में पकाकर बासमती चावल, दो रोटियों और सलाद के साथ भरपूर साझा मील के रूप में पैक करते हैं। तले प्याज़ और धनिये से सजाकर दो लोगों के लिए परोसते हैं।'),
  ('biryani-kebab-duo', 'बिरयानी और कबाब डुओ', 'चिकन दम बिरयानी, दो सीख कबाब और रायता', 'चिकन दम बिरयानी को दम पर पकाते हैं और दो सीख कबाब ऑर्डर पर अंगारों पर भूनते हैं। पुदीना, नींबू और तले प्याज़ से सजाकर रायते के साथ दो लोगों के लिए परोसते हैं।'),
  ('bihari-veg-thali-deluxe', 'बिहारी वेज थाली डिलक्स', 'लिट्टी चोखा, दाल, मौसमी सब्ज़ी, चावल, रोटी और मिठाई', 'इस भरपूर बिहारी स्वाद वाली थाली में लिट्टी चोखा, दाल, मौसमी सब्ज़ी, चावल, रोटी और मिठाई शामिल हैं। घी, अचार और ताज़े धनिये के साथ एक व्यक्ति के पूरे मील के रूप में परोसते हैं।'),
  ('aloo-paratha-curd', 'दही के साथ आलू पराठा', 'मसालेदार आलू, गेहूँ का पराठा और ठंडा दही', 'गेहूँ के पराठे में मसालेदार आलू भरकर थोड़े घी में तवे पर सुनहरा सेंकते हैं। ऊपर से सफ़ेद मक्खन और आम के अचार के साथ, ठंडा दही परोसते हैं।'),
  ('chole-bhature', 'छोले भटूरे', 'धीमी आँच पर पके छोले और फूले हुए दो भटूरे', 'छोलों को बड़ी इलायची के साथ धीमी आँच पर मसालेदार ग्रेवी में पकाते हैं और भटूरे ऑर्डर पर तलते हैं। प्याज़, नींबू और धनिये के साथ; अचार सहित गरम परोसते हैं।'),
  ('masala-omelette-paratha', 'पराठे के साथ मसाला ऑमलेट', 'देसी अंडे, प्याज़, टमाटर, हरी मिर्च और नरम पराठा', 'देसी अंडों में प्याज़, टमाटर और हरी मिर्च मिलाकर ताज़ा ऑमलेट बनाते हैं और तवे के पराठे के साथ मोड़कर परोसते हैं। धनिये और पुदीने की चटनी के साथ गरम परोसते हैं।'),
  ('anda-bhurji-pav', 'अंडा भुर्जी पाव', 'भुना अंडा, टमाटर, प्याज़ और मक्खन लगा पाव', 'अंडे की भुर्जी को टमाटर और प्याज़ के साथ गरम तवे पर ताज़ा पकाते हैं। धनिये और नींबू से सजाकर मक्खन लगे दो पाव के साथ परोसते हैं।'),
  ('poha-masala', 'इंदौरी मसाला पोहा', 'नरम पोहा, प्याज़, करी पत्ते और भुनी मूँगफली', 'पोहा, प्याज़, करी पत्ते और भुनी मूँगफली को हल्की भाप देकर राई के तड़के में मिलाते हैं। ऊपर से सेव, धनिया और नींबू डालकर गरम परोसते हैं।'),
  ('jalebi-rabri-breakfast', 'जलेबी रबड़ी नाश्ता', 'कुरकुरी जलेबी, केसर की रबड़ी और इलायची की हल्की खुशबू', 'जलेबी को ताज़ा तलकर ठंडी केसरिया रबड़ी के साथ परोसते हैं। पिस्ते और गुलाब से सजाकर एक खास मीठे नाश्ते के रूप में गरम-ठंडा आनंद दें।')
) as t(slug, name_hi, short_description_hi, description_hi)
where p.slug = t.slug
  and p.id::text like '77777777-%';

update public.product_images as pi
set alt_text = p.name_hi || ' — बाइट्स बॉक्स'
from public.products as p
where pi.product_id = p.id
  and p.id::text like '77777777-%'
  and pi.is_primary
  and p.name_hi is not null;
